<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Serenova Hotel | Dodoma</title><meta name="description" content="Serenova Hotel in Dodoma — elegant rooms, dining and warm Tanzanian hospitality."><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#18221f;background:#faf8f3}a{text-decoration:none;color:inherit}.nav{position:absolute;z-index:5;top:0;left:0;right:0;display:flex;justify-content:space-between;align-items:center;padding:25px 6%;color:#fff}.logo{font-size:24px;font-weight:900;letter-spacing:1px}.logo span{color:#e2bd72}.links{display:flex;gap:27px;font-size:14px;font-weight:700}.links a:hover{color:#e2bd72}.hero{min-height:92vh;display:grid;place-items:center;text-align:center;color:#fff;padding:110px 6% 70px;background:linear-gradient(180deg,rgba(5,15,12,.15),rgba(5,15,12,.82)),url('https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=2000&q=85') center/cover}.hero h1{font-size:clamp(48px,7vw,88px);line-height:.98;max-width:950px;margin:15px auto}.hero p{max-width:680px;margin:0 auto 32px;font-size:19px;line-height:1.7;color:#f4f1e9}.eyebrow{color:#b17e37;text-transform:uppercase;letter-spacing:3px;font-size:12px;font-weight:900}.hero .eyebrow{color:#e2bd72}.btn{display:inline-block;background:#c99d52;color:#fff;padding:15px 25px;border-radius:4px;font-weight:800;border:1px solid #c99d52}.btn.alt{background:transparent;border-color:#fff;margin-left:8px}.section{padding:85px 7%}.title{font-size:43px;margin:10px 0 14px}.intro{max-width:680px;color:#68736f;line-height:1.8}.rooms{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:38px}.card{background:#fff;border:1px solid #e5dfd4;box-shadow:0 14px 40px rgba(20,30,26,.07);overflow:hidden}.card img{width:100%;height:235px;object-fit:cover;display:block}.card-body{padding:24px}.card h3{font-size:23px;margin:0 0 9px}.muted{color:#68736f;line-height:1.7}.price{font-size:20px;font-weight:900;color:#9a702f;margin:18px 0}.dark{background:#1b2a25;color:#fff}.dark .title{color:#fff}.amenities{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:38px}.amenity{padding:28px 22px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.04);line-height:1.6}.amenity-icon{font-size:28px}.amenity b{display:block;margin:9px 0}.split{display:grid;grid-template-columns:1fr 1fr;gap:55px;align-items:center}.photo{width:100%;height:430px;object-fit:cover}.booking{background:#f0ece3}.box{background:#fff;padding:30px;border:1px solid #e2dccf;box-shadow:0 14px 40px rgba(20,30,26,.06)}.form{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form label{font-size:12px;font-weight:800;color:#4e5955}.form input,.form select{width:100%;padding:13px;margin-top:7px;border:1px solid #d6d0c5;background:#fff;border-radius:3px;font:inherit}.full{grid-column:1/-1}.footer{padding:36px 7%;background:#111916;color:#c9d0cc;display:flex;justify-content:space-between}.small{font-size:13px}@media(max-width:800px){.links{display:none}.hero{min-height:82vh}.rooms,.amenities,.split{grid-template-columns:1fr}.section{padding:65px 6%}.photo{height:300px}.form{grid-template-columns:1fr}.full{grid-column:auto}.btn.alt{margin:10px 0 0}.footer{display:block}.footer div+div{margin-top:12px}}</style></head><body><header class="nav"><div class="logo">SERENOVA <span>HOTEL</span></div><nav class="links"><a href="#home">Home</a><a href="#rooms">Rooms</a><a href="#dining">Dining</a><a href="#facilities">Facilities</a><a href="#booking">Book</a></nav></header><section class="hero" id="home"><div><div class="eyebrow">Welcome to Serenova</div><h1>Your peaceful stay in Dodoma.</h1><p>Elegant rooms, local flavours and thoughtful hospitality for business trips, family stays and quiet escapes.</p><a class="btn" href="#booking">Book a room</a><a class="btn alt" href="#rooms">Explore rooms</a></div></section><section class="section" id="rooms"><div class="eyebrow">Stay your way</div><h2 class="title">Rooms made for real rest.</h2><p class="intro">Comfortable spaces with modern essentials, generous beds and the calm atmosphere you need after a busy day.</p><div class="rooms"><article class="card"><img src="https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1000&q=85" alt="Deluxe room"><div class="card-body"><h3>Deluxe Room</h3><p class="muted">King bed, private bathroom, work desk and complimentary Wi‑Fi.</p><div class="price">TZS 180,000 / night</div><a class="btn" href="#booking">Reserve</a></div></article><article class="card"><img src="https://images.unsplash.com/photo-1591088398332-8a7791972843?auto=format&fit=crop&w=1000&q=85" alt="Executive suite"><div class="card-body"><h3>Executive Suite</h3><p class="muted">Spacious suite with lounge area, premium bedding and city views.</p><div class="price">TZS 280,000 / night</div><a class="btn" href="#booking">Reserve</a></div></article><article class="card"><img src="https://images.unsplash.com/photo-1584132967334-10e028bd69f7?auto=format&fit=crop&w=1000&q=85" alt="Family room"><div class="card-body"><h3>Family Room</h3><p class="muted">Comfortable family layout with extra sleeping space and breakfast option.</p><div class="price">TZS 240,000 / night</div><a class="btn" href="#booking">Reserve</a></div></article></div></section><section class="section dark" id="facilities"><div class="eyebrow" style="color:#e2bd72">Everything you need</div><h2 class="title">Hotel facilities</h2><div class="amenities"><div class="amenity"><span class="amenity-icon">☕</span><b>Restaurant & Café</b>Breakfast, lunch and dinner with local and international choices.</div><div class="amenity"><span class="amenity-icon">📶</span><b>Fast Wi‑Fi</b>Reliable connectivity for work, streaming and staying in touch.</div><div class="amenity"><span class="amenity-icon">🏊</span><b>Swimming Pool</b>A relaxed outdoor space for cooling down and unwinding.</div><div class="amenity"><span class="amenity-icon">🚗</span><b>Secure Parking</b>Convenient on-site parking for hotel guests.</div></div></section><section class="section" id="dining"><div class="split"><div><div class="eyebrow">Taste Tanzania</div><h2 class="title">Good food, warm evenings.</h2><p class="intro">Enjoy fresh meals for relaxed mornings, business lunches and memorable evenings. Our kitchen brings together familiar favourites and Tanzanian flavours.</p><a class="btn" href="#booking">Plan your stay</a></div><img class="photo" src="https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1100&q=85" alt="Hotel dining"></div></section><section class="section booking" id="booking"><div class="split"><div><div class="eyebrow">Reservations</div><h2 class="title">Make your stay simple.</h2><p class="intro">Send a booking request and our reception team can confirm availability and your final rate.</p><p><b>Reception:</b> +255 700 000 000<br><b>Email:</b> reservations@serenovahotel.co.tz<br><b>Location:</b> Dodoma, Tanzania</p></div><div class="box"><form class="form" onsubmit="event.preventDefault();alert('Thank you! Your booking request has been received. Our reception team will contact you.');"><label>Check-in<input type="date" required></label><label>Check-out<input type="date" required></label><label>Room<select><option>Deluxe Room</option><option>Executive Suite</option><option>Family Room</option></select></label><label>Guests<select><option>1 guest</option><option>2 guests</option><option>3 guests</option><option>4 guests</option></select></label><label class="full">Guest name<input type="text" placeholder="Your full name" required></label><label class="full">Phone<input type="tel" placeholder="+255 7XX XXX XXX" required></label><button class="btn full" type="submit">Request booking</button></form></div></div></section><footer class="footer"><div><b style="color:#fff">SERENOVA HOTEL</b><br><span class="small">Dodoma, Tanzania</span></div><div class="small">© 2026 Serenova Hotel · Hospitality with heart · Deployment target: /htdocs/</div></footer></body></html>